import { createHash } from 'node:crypto';

const PERSONAL_OR_LIVE_RE = /(đơn của tôi|đơn hàng|công nợ|tồn kho|còn mấy|lịch hẹn|hồ sơ của em|trạng thái|số dư)/i;
const ENTITY_CODE_RE = /\b(?:[A-Z]{2,5}[-_]?\d{2,4}(?:\.\d{2})?|starter|growth|enterprise|q\d{1,2}|quận\s+\d+)\b/gi;

export interface CacheLookupResult {
  hit: boolean;
  reason: string;
  cachedAnswer?: string;
  similarity?: number;
}

export function checkCacheEligibility(query: string, turnCount: number): boolean {
  if (turnCount > 2) return false; // Hội thoại nối tiếp sâu dễ phụ thuộc đại từ ẩn
  if (PERSONAL_OR_LIVE_RE.test(query)) return false; // Dữ liệu sống/PII đi thẳng SQL RLS
  if (/\b0[35789]\d{8}\b/.test(query)) return false; // Chứa SĐT cá nhân
  return true;
}

export function extractEntitySignature(query: string): string {
  const matches = (query.match(ENTITY_CODE_RE) || [])
    .map((m) => m.toLowerCase().replace(/\s+/g, ''))
    .sort();
  const unique = Array.from(new Set(matches));
  return unique.length > 0 ? unique.join('|') : 'GENERIC_STATIC';
}

export async function lookupEntitySafeSemanticCache(params: {
  query: string;
  turnCount: number;
  kbVersion: string;
  tenantId: string;
  embedFn: (text: string) => Promise<number[]>;
  redisVectorSearch: (args: {
    tenantId: string;
    kbVersion: string;
    entitySignature: string;
    vector: number[];
    minCosine: number;
  }) => Promise<{ answer: string; cosine: number } | null>;
}): Promise<CacheLookupResult> {
  if (!checkCacheEligibility(params.query, params.turnCount)) {
    return { hit: false, reason: 'BYPASS_DYNAMIC_OR_PERSONAL' };
  }

  const entitySignature = extractEntitySignature(params.query);
  const queryVector = await params.embedFn(params.query.trim().toLowerCase());

  const matched = await params.redisVectorSearch({
    tenantId: params.tenantId,
    kbVersion: params.kbVersion,
    entitySignature,
    vector: queryVector,
    minCosine: 0.94,
  });

  if (!matched) {
    return { hit: false, reason: 'MISS_OR_ENTITY_MISMATCH' };
  }

  return {
    hit: true,
    reason: `SAFE_HIT:${entitySignature}`,
    cachedAnswer: matched.answer,
    similarity: matched.cosine,
  };
}

export function buildCacheRecordKey(tenantId: string, kbVersion: string, query: string): string {
  const sig = extractEntitySignature(query);
  const hash = createHash('sha256').update(`${kbVersion}:${sig}:${query}`).digest('hex').slice(0, 16);
  return `semcache:${tenantId}:${kbVersion}:${sig}:${hash}`;
}
